INSERT INTO `achievement_locale` (`ID`, `locale`, `Description_lang`, `Title_lang`, `Reward_lang`, `VerifiedBuild`) VALUES
(63325, 'itIT', 'Ottieni 5 Granuli della Ricerca Omniale da usare nel Foglio dell\'Omnium.', 'Studi sul Foglio dell\'Omnium', 'Ricompensa decorazione: Simulacro dell\'Omnium dei Solealto', 68974),
(62903, 'itIT', 'Dissipa 5 Tempeste su Val.', 'Stranezza climatica: Val', 'Ricompensa mascotte: sblocca l\'acquisto di Capitan Fochindus', 68974),
(63343, 'itIT', 'Segna un gol con la Palla da Allenamento Calciabile a Lunargenta mentre indossi un\'Insegna della Partecipazione.', 'Gol!', 'Ricompensa decorazione: Globo Prezioso di Azeroth, Orgoglio dell\'Orda in Cornice e Orgoglio dell\'Alleanza in Cornice', 68974),
(61336, 'itIT', 'Onora le fiamme di Midnight.', 'Custode delle Fiamme di Midnight', '', 68974),
(61335, 'itIT', 'Onora le fiamme di Midnight.', 'Guardiano delle Fiamme di Midnight', '', 68974),
(61936, 'itIT', 'Sconfiggi l\'Avanguardia Lucecieca mentre tutto il tuo gruppo ha Aura Massima nel Pinnacolo del Vuoto in modalità Normale o superiore.', 'Collezione di aure', '', 68974),
(61911, 'itIT', 'Sconfiggi Vaelgor ed Ezzorak dopo che tutti i personaggi hanno spezzato tutti i legami di Zona del Nulla entro 3 secondi nel Pinnacolo del Vuoto in modalità Normale o superiore.', 'Pronti, partenza, spezza!', '', 68974),
(61514, 'itIT', 'Sconfiggi il Re Caduto Salhadaar dopo che tutti si sono messi in /ginocchio davanti a lui prima della battaglia al Pinnacolo del Vuoto in modalità Normale o superiore.', 'Questo è tradimento', '', 68974),
(61381, 'itIT', 'Sconfiggi Belo\'ren, Prole di Al\'ar, dopo avere infuso l\'Uovo del Pozzo Solare di Luce e magia del Vuoto nella Marcia su Quel\'Danas in modalità Normale o superiore.', 'Crisi ovistenziale', '', 68974),
(61346, 'itIT', 'Sconfiggi la Corona del Cosmo dopo aver eliminato una Mostruosità Carnosa e aver riportato tutta la sua carne alla Vacuità al Pinnacolo del Vuoto in modalità Normale o superiore.', 'E alla fine tornerà di nuovo', '', 68974),
(61611, 'itIT', 'Sconfiggi Scoccare della Mezzanotte nella Marcia su Quel\'Danas in modalità Mitica con un gruppo di gilda.', 'Gilda: Scoccare della Mezzanotte [M]', '', 68974),
(61380, 'itIT', 'Compi le imprese delle incursioni elencate qui sotto.', 'Gloria dell\'incursore di Midnight', 'Cavalcatura: Straziatore Tenebroso', 68974),
(62874, 'itIT', 'Compi le seguenti imprese:', 'Un viaggio attraverso le stelle', 'Ricompensa: sblocca Corazza Nulla Fatuoforgiata per l\'acquisto', 68974);
INSERT INTO `adventure_journal_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `ButtonText_lang`, `RewardDescription_lang`, `ContinueDescription_lang`, `VerifiedBuild`) VALUES
(909, 'itIT', 'Foglio dell\'Omnium - Nuove informazioni', 'I Magistri hanno delle informazioni aggiuntive per potenziare ulteriori rune nel Foglio dell\'Omnium.', 'Accetta missione', 'Ricompensa con un Granulo della Ricerca Omniale per potenziare un\'altra runa nel Foglio dell\'Omnium.', '', 68974);
INSERT INTO `area_table_locale` (`ID`, `locale`, `AreaName_lang`, `VerifiedBuild`) VALUES
(15966, 'itIT', 'Tana di Predaxas', 68974);
INSERT INTO `battle_pet_species_locale` (`ID`, `locale`, `Description_lang`, `SourceText_lang`, `VerifiedBuild`) VALUES
(4618, 'itIT', 'MODALITÀ RILASSAMENTO: ATTIVA.\nLIVELLO RILASSAMENTO: MASSIMO.\nTEMPERATURA INTERNA: BASSA.', '|cFFFFD200Promozione|r |n', 68974),
(4617, 'itIT', 'DIRETTIVA PRIMARIA: COMPIERE GESTA EROICHE.\nGESTA EROICHE PREFERITE: ENTUSIASMANTI.\nDIRETTIVA SECONDARIA: DIVENTARE EROE.\nTIPO DI EROE PREFERITO: GRANDE.', '|cFFFFD200Promozione|r |n', 68974),
(4949, 'itIT', 'Un residuo persistente del tentativo di Fyrakk di corrompere Amirdrassil.', '|cFFFFD200Mercante: |rXydan|n|cFFFFD200Zona: |rValdrakken|n|cFFFFD200Costo: |r2.200|Hcurrency:1166|h|TInterface\\ICONS\\PVECurrency-Justice.blp:0|t|h', 68974),
(5074, 'itIT', 'A differenza della maggior parte delle Ombre del Vuoto della Tempesta del Vuoto, Silento preferisce la pace e la tranquillità del silenzio, anche se ciò significa mettere a tacere i membri più loquaci della sua specie.', '|cFFFFD200Imprese:|r Compimento dello Scontro Finale: Val e Compimento dello Scontro Finale: Naigtal |n|cFFFFD200Mercante: |rKifaan|n|cFFFFD200Zona: |rVal o Naigtal|n|cFFFFD200Costo: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 68974),
(5073, 'itIT', 'Questa piccoletta è pronta a scatenarsi per cercare di essere all\'altezza dei suoi antenati. Inizierà da piccoli ragni, per poi passare a prede sempre più grandi.', '|cFFFFD200Impresa:|r Massacro dell\'Ultradonte|n|cFFFFD200Mercante: |rKifaan|n|cFFFFD200Zona: |rVal o Naigtal|n|cFFFFD200Costo: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 68974),
(4898, 'itIT', 'Capitan Fochindus adora il pesce congelato ed è il migliore amico di chiunque ne abbia.', '|cFFFFD200Impresa:|r Stranezza climatica: Val|n|cFFFFD200Mercante: |rKifaan|n|cFFFFD200Zona: |rNaigtal o Val|n|cFFFFD200Costo: |r50|Hitem:238365|h|TInterface\\ICONS\\INV_Misc_Fish_41.blp:0|t|h |n|n', 68974);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(317639, 'itIT', 'Il Comandante Tala\'saan si toglie il Mantello del Velo di Luce e fa un passo avanti.', '', 68974),
(314421, 'itIT', 'ARGH!', '', 68974),
(314420, 'itIT', 'NIPOTE, ATTENTO!', '', 68974),
(314419, 'itIT', 'NIENTE HASH\'EY!', '', 68974),
(314418, 'itIT', 'Chesto potere significa NIENTE LOA,', '', 68974),
(314417, 'itIT', 'No!', '', 68974),
(314416, 'itIT', 'Lasciala!', '', 68974),
(314415, 'itIT', 'Chist\'è magia oscura!', '', 68974),
(314414, 'itIT', 'Zul\'jan!', '', 68974),
(314413, 'itIT', '(gemito)', '', 68974),
(314412, 'itIT', 'Chesta dev\'essere... la chiave per...', '', 68974),
(314411, 'itIT', 'L\'aggio trovata!', '', 68974),
(314410, 'itIT', 'Ah!', '', 68974),
(314408, 'itIT', 'ti assicuro... che capirà.', '', 68974),
(314407, 'itIT', 'E dopo che il potere di Ula\'tek sarà tuo', '', 68974),
(314406, 'itIT', 'Prendi la chiave, Zul\'jan.', '', 68974),
(314405, 'itIT', 'Quando vedrà lo zio nostro...', '', 68974),
(314404, 'itIT', 'I Loa ce l\'hanno nelle grinfie loro...', '', 68974),
(314403, 'itIT', 'Che ne sarà della sorella mia?', '', 68974),
(314402, 'itIT', 'Per finire ciò che io e tuo nonno abbiamo iniziato.', '', 68974),
(314401, 'itIT', 'e liberarli dalle vane promesse dei Loa.', '', 68974),
(314400, 'itIT', 'Per proteggere il futuro della nostra gente', '', 68974),
(314399, 'itIT', 'e ho bisogno del tuo aiuto, Zul\'jan.', '', 68974),
(314398, 'itIT', 'Malacrass', '', 68974),
(314397, 'itIT', 'Esatto...', '', 68974),
(314396, 'itIT', 'Allora devi essere...', '', 68974),
(314395, 'itIT', 'Conoscevi il nonno mio?', '', 68974),
(314394, 'itIT', 'Io e Zul\'jin abbiamo provato a cambiarlo...', '', 68974),
(314393, 'itIT', 'Purtroppo, chisto è lu destino che spetta alla nostra gente.', '', 68974),
(314392, 'itIT', '...e dov\'erano mentre esalava l\'ultimo respiro?', '', 68974),
(314391, 'itIT', 'Una vita di devozione ai Loa...', '', 68974),
(314390, 'itIT', 'Che tragedia.', '', 68974),
(314389, 'itIT', 'No no no, non volevo...', '', 68974),
(314388, 'itIT', 'No...', '', 68974),
(314387, 'itIT', 'È morto, Zul\'jan.', '', 68974),
(314386, 'itIT', 'ZIO!', '', 68974),
(314385, 'itIT', 'Zio?!?', '', 68974),
(314384, 'itIT', '(colpo di tosse)', '', 68974),
(310355, 'itIT', 'Io cercherò il componente mancante nella Torre degli Albastella. Raggiungimi appena puoi, $n. E Rommath, buona fortuna.', '', 68974),
(317801, 'itIT', '<Tala\'saan valuta la domanda, il suo sguardo volge lontano per un breve istante.>\n\nLa Capitana Fareeya non si unirà a quest\'operazione.\n\nIo sarò il suo tramite sulle forze dei Forgialuce schierati per la missione di Maella.\n\nCon la perdita del Gran Esarca e di innumerevoli altri, l\'Armata della Luce ha bisogno della sua guida, ora più che mai.\n\nFortunatamente, non siamo rimasti del tutto soli. Come hai visto, Baraat e Y\'mera si sono uniti a noi.\n\nDopo molte proteste, Enaara li ha accettati entrambi. Tuttavia, anche lei resterà indietro con Sorvos e la capitana.', '', 68974),
(317797, 'itIT', '<Il volto di Tala\'saan si irrigidisce.>\n\nMolti miei fratelli e sorelle sono... andati perduti nel vortice urlante del Pinnacolo del Vuoto.\n\nMolti altri hanno subito ferite che trascendono il dolore fisico.\n\nSo cos\'è accaduto a molti di coloro che si trovavano nel Pinnacolo, $n. L\'hai visto anche tu, no? Rabbia... confusione... disperazione.\n\nQuesta guerra ha colto molte buone anime. Non potrei mai chiedere a Fareeya di dare più di quanto possa.', '', 68974),
(317795, 'itIT', 'Sono Tala\'saan, comandante del Velo di Luce nell\'Armata della Luce.\n\nPer sua richiesta, ho accettato di contribuire alla missione della Fendivarchi Maella, in cerca delle forze del Vuoto e degli Hal\'hadar.\n\nAbbiamo un trascorso complesso con questi nemici, ma siamo veterani dei viaggi verso reami ignoti.\n\nColoro che vedi radunati qui sono tra i migliori al servizio dell\'unità del Velo di Luce.', '', 68974),
(317656, 'itIT', '', 'Tul\'amar stringe i denti e rimane in silenzio per un attimo. Il suo occhio sano guizza verso di te e poi torna su Tala\'saan.', 68974),
(317572, 'itIT', 'Terrò d\'occhio la mia... o meglio, la nostra nuova pedina.', '', 68974),
(317571, 'itIT', 'Il nostro lavoro non è ancora finito, ma non temere: Impotus non ci metterà i bastoni tra le ruote. Si rinchiuderà nell\'Acropoli, assaporando la sua vittoria.', '', 68974),
(317109, 'itIT', 'Questo tugurio ghiacciato è debole. Ci sono altri mondi che sarebbero assai più semplici... quasi perfetti.', '', 68974),
(316762, 'itIT', 'La Fendivarchi Maella ci ha chiesto di accompagnare le sue forze durante questa spedizione.\n\nLe conoscenze del Vuoto e delle operazioni degli Hal\'hadar di Veraan la rendono una risorsa preziosa per la missione.\n\nPer quanto riguarda me, c\'è sempre bisogno di un tecnomante per disassemblare qualcosa!', '', 68974),
(316750, 'itIT', '', 'Secondo gli archivi di Antorus, la presenza della Legione qui su Val era scarsa. Chissà come mai.\n\nGran parte di questo mondo è protetto da enormi tempeste di ghiaccio, capaci di fare a pezzi lo scafo delle navi della Legione.\n\nAlmeno due vascelli da invasione furono perduti nel loro tentativo di conquistare questo mondo.\n\nAlla fine riuscirono a stabilire qualche fortezza, ma non erano altro che avamposti remoti.\n\nA quanto pare, se qualcuno veniva stanziato su Val, era una punizione a causa dei suoi continui fallimenti.', 68974),
(316562, 'itIT', '', '<L\'Arcimaga Y\'mera sembra concentrata nel suo compito, mentre inserisce dei simboli runici nella console a una velocità incredibile.>\n\nL\'energia del Vuoto a sud ha origine dall\'Acropoli.\n\nSecondo questi dati, la fortezza si estende in profondità sotto il ghiaccio.', 68974),
(316520, 'itIT', '', 'Gli Illidari conoscono questo inferno congelato meglio di chiunque altro. La Legione lo chiamava \"Val\", e usava la sua temperatura gelida per interrogare i prigionieri.\n\nUna terra desolata e fredda sembra il luogo perfetto dove un Domanaar possa acclimatarsi.\n\n<Maella lancia un\'occhiata non particolarmente subdola a Decimus.>', 68974),
(316419, 'itIT', '<Il segnalatore ha due pulsanti per selezionare la destinazione del teletrasporto: Lunargenta o la Tempesta del Vuoto. Resisti alla voglia di premerli entrambi.>', '<Il segnalatore ha due pulsanti per selezionare la destinazione del teletrasporto: Lunargenta o la Tempesta del Vuoto. Resisti alla voglia di premerli entrambi.>', 68974),
(316274, 'itIT', '', 'Grazie alle oloimpronte che hai recuperato, sappiamo da dove gli Eterei stanno recuperando i manufatti Draenei.\n\nC\'è una cripta costruita dalla mia gente, sotto l\'isola.\n\nGli Hal\'hadar stanno mietendo sia i guardiani all\'interno che gli spiriti irrequieti dei morti.\n\nI loro registri indicano che ci sono svariati vigilanti nella tomba, ma finora i loro sforzi non hanno avuto successo.\n\nCon un po\' di fortuna, potremmo riuscire a interrompere le loro operazioni.\n\nTala\'saan ci guiderà dentro la cripta.', 68974),
(316214, 'itIT', '', '<Gli occhi dell\'Arcimaga Y\'mera si spalancano quando prende uno dei cristalli dalle tue mani.>\n\nQueste rune sono in lingua Draenei, $n. Non dovrebbe sorprendermi.\n\nGli Hal\'hadar sono dei saccheggiatori per quanto riguarda la tecnologia, prendono tutto quello che possono dai mondi che invadono.\n\nDevono aver scoperto la tecnologia dei cristalli del nostro popolo da qualche parte, proprio come hanno scoperto le nostre Corazze da Guerra.\n\nIo mi occuperò di esaminare questo. Tu porta gli altri a Kifaan.Sta documentando la tecnologia degli Hal\'hadar.\n\nSarà utile chiedere l\'opinione di un tecnomante del Consorzio su questa scoperta.', 68974),
(316212, 'itIT', '', '<L\'Arcimaga Y\'mera sembra concentrata sul suo compito, mentre inserisce dei simboli runici nella console a una velocità incredibile.>\n\nCon un po\' di fortuna e un bel po\' di lavoro di decifrazione, dovremmo riuscire a capire cos\'è che i nostri nemici cercano a Naigtal.\n\nC\'è molto da scoprire sugli Hal\'hadar, $ucampione:campionessa;.\n\nNon dobbiamo sprecare questa opportunità.', 68974),
(314754, 'itIT', 'I tuoi nemici sono dietro di te. Girati!', 'I tuoi nemici sono dietro di te. Girati!', 68974),
(313932, 'itIT', '', 'La Fendivarchi Maella fissa con rabbia la proiezione di Decimus.', 68974),
(313749, 'itIT', '', 'È arrivato il momento? È stata la Fendivarchi Maella a mandarti? Mi farebbe comodo il tuo aiuto prima di partire!\n\nHo modificato la nostra tecnologia del Velo di Luce usando un semplice incantesimo di occultamento e quel legame.\n\nCombinando le due cose, credo di poter occultare il nostro intero accampamento quando arriveremo a terra.\n\nMa prima, mi servirà una cavia invisibile per testare il limite alla distanza del legame.\n\nPuoi aiutarmi?', 68974),
(310380, 'itIT', 'Sgominare un imperatore Domanaar non ha lo stesso impatto dell\'uccidere un leader mortale.', '', 68974),
(310377, 'itIT', '', 'Pertinax non sarà più un problema per noi, grazie a qualcuno qui presente.', 68974),
(310376, 'itIT', 'E se il loro \"Imperatore\" dovesse graziarti con la sua presenza, ti sarei molto riconoscente se ti sbarazzassi di lui.', '', 68974),
(310375, 'itIT', '', 'Neutralizzare la presenza del Vuoto qui farà guadagnare del tempo prezioso ai nostri. Va\' e semina il caos.', 68974),
(310366, 'itIT', 'Luce... Vile... Vuoto. La ricetta perfetta per fomentare le tensioni. Delizioso.', '', 68974),
(309048, 'itIT', 'Gli Hal\'hadar hanno armato le loro scialuppe volanti con delle torrette per \"difendersi\". Vediamo quanto sono forti queste difese, che ne dici?', '', 68974),
(309047, 'itIT', 'Non so molto su questi \"Hal\'hadar\", ma sembrano un nemico più formidabile della Guardia dell\'Ombra. Ti suggerisco di sfoltire le loro fila per non farti travolgere più avanti.', '', 68974),
(309020, 'itIT', '', 'I nostri esploratori Forgialuce hanno trovato le prove di un\'antica creatura del Vuoto che un tempo viveva qui. Raccogli dei campioni per la nostra ricerca.', 68974),
(309018, 'itIT', 'I tuoi esploratori più... \"avventurosi\" hanno cercato di sfruttare le risorse instabili di questo mondo. Cerca di evitare degli sfortunati incidenti mentre le raccogli.', '', 68974),
(309015, 'itIT', '', 'Sabotare la rete di portali dei Domanaar metterà un freno alla loro invasione di Azeroth. Fai quello che puoi e rallenta i loro sforzi.', 68974),
(309014, 'itIT', 'Che novità, un\'altra \"minaccia\" mette a repentaglio la tua missione. Distruggi, elimina e vinci.', '', 68974),
(318546, 'itIT', 'La Terrazza dei Magistri è da sempre un luogo di apprendimento.\n\nUn bastione di conoscenza, dove le idee possono essere condivise senza divisioni né orgoglio personale.\n\nEppure, per quanto mi sforzi, mi è difficile guardare coloro che hanno fatto ritorno e non provare...\n\n<La Magistra serra i denti e tace.>', 'La Terrazza dei Magistri è da sempre un luogo di apprendimento.\n\nUn bastione di conoscenza, dove le idee possono essere condivise senza divisioni né orgoglio personale.\n\nEppure, per quanto mi sforzi, mi è difficile guardare coloro che hanno fatto ritorno e non provare...\n\n<La Magistra serra i denti e tace.>', 68974),
(318542, 'itIT', '<La Magistra Alta Elfa sospira mentre ti avvicini.>\n\nTi prego, non sgridarmi perché sono qui... non sopporterei un altro singolo sguardo torvo o commento.\n\nVoglio solo imparare la magia ed esercitarmi con nuovi incantesimi. Sto chiedendo troppo?\n\nQuesti battibecchi mi stanno facendo impazzire!', '<La Magistra Alta Elfa sospira mentre ti avvicini.>\n\nTi prego, non sgridarmi perché sono qui... non sopporterei un altro singolo sguardo torvo o commento.\n\nVoglio solo imparare la magia ed esercitarmi con nuovi incantesimi. Sto chiedendo troppo?\n\nQuesti battibecchi mi stanno facendo impazzire!', 68974),
(317974, 'itIT', 'Padroneggiare e comprendere la magia è sempre stata la nostra via. La via dei Magistri.\n\nSpero davvero che qualcuno dei nostri, con una mentalità più aperta, possa aiutare gli altri a comprendere le nostre intenzioni nello studiare il Vuoto.\n\nE non è certo nostra intenzione esiliare coloro che non vogliono partecipare a questo studio.', 'Padroneggiare e comprendere la magia è sempre stata la nostra via. La via dei Magistri.\n\nSpero davvero che qualcuno dei nostri, con una mentalità più aperta, possa aiutare gli altri a comprendere le nostre intenzioni nello studiare il Vuoto.\n\nE non è certo nostra intenzione esiliare coloro che non vogliono partecipare a questo studio.', 68974),
(317973, 'itIT', 'Secondo Veldharin, i primi Cercatori di Sapienza indagarono sulla presenza oscura che i nostri antenati percepirono a Tirisfal.\n\nNessuno sa con precisione cosa trovarono, ma a quanto pare solo alcuni di loro fecero ritorno con la mente ancora intatta.\n\nA prescindere da cosa videro o scoprirono, quell\'evento fu sufficiente affinché Dath\'Remar bandisse la magia del Vuoto.\n\nPensi che Umbric vi abbia scrutato dentro? Pensi che sarà concesso farlo anche a noi?', 'Secondo Veldharin, i primi Cercatori di Sapienza indagarono sulla presenza oscura che i nostri antenati percepirono a Tirisfal.\n\nNessuno sa con precisione cosa trovarono, ma a quanto pare solo alcuni di loro fecero ritorno con la mente ancora intatta.\n\nA prescindere da cosa videro o scoprirono, quell\'evento fu sufficiente affinché Dath\'Remar bandisse la magia del Vuoto.\n\nPensi che Umbric vi abbia scrutato dentro? Pensi che sarà concesso farlo anche a noi?', 68974),
(317972, 'itIT', '<Il Magistro sospira mentre ti avvicini.>\n\nTi prego, non sgridarmi perché sono qui... non sopporterei un altro singolo sguardo torvo o commento.\n\nVoglio solo imparare la magia ed esercitarmi con nuovi incantesimi. Sto chiedendo troppo?\n\nQuesti battibecchi mi stanno facendo impazzire, e sai che non è facile, visto il mio trascorso a fissare buchi neri!', '<Il Magistro sospira mentre ti avvicini.>\n\nTi prego, non sgridarmi perché sono qui... non sopporterei un altro singolo sguardo torvo o commento.\n\nVoglio solo imparare la magia ed esercitarmi con nuovi incantesimi. Sto chiedendo troppo?\n\nQuesti battibecchi mi stanno facendo impazzire, e sai che non è facile, visto il mio trascorso a fissare buchi neri!', 68974),
(317917, 'itIT', 'A dire il vero, non sono certo che fosse sua intenzione.\n\nIl suo tradimento ai danni dell\'assemblea e del nostro popolo è stato ripugnante, tuttavia non credo fosse sua intenzione danneggiare l\'Omnium.\n\nNon avrebbe mai distrutto un archivio pieno di conoscenze proibite che gli erano state negate per così tanto tempo.\n\nSemmai, mi sarei aspettato che tentasse di rubare l\'intero Omnium.\n\nForse è per questo che ne ha rubato solo un pezzo.', '', 68974),
(317753, 'itIT', '<Socchiude gli occhi vitrei.>\n\nUna... domanda appropriata, suppongo.\n\nÈ... Era... un nodo di conoscenza severamente proibito, come decretato da Dath\'Remar.\n\nQuando ci stabilimmo sulle coste di Tirisfal, i nostri antenati riscontrarono un\'oscurità aggrappata alla terra.\n\nI sussurri fecero impazzire molti, si nutrirono della nostra paranoia, istigarono la paura e l\'invidia tra i nostri fratelli ormai stanchi.\n\nDath\'Remar decise di scoprire da dove provenisse tale magia, per cui inviò le prime unità dei Cercatori.\n\nIn pochi sanno cosa trovarono o incontrarono, ma fu abbastanza perché Dath\'Remar ne interrompesse lo studio.\n\nSolo i Magistri più fidati e abili ottennero il permesso di scandagliare il sapere contenuto nella Magicola del Vuoto.', '', 68974),
(317750, 'itIT', 'Domanda eccellente! Vediamo...\n\nC\'è la Magicola Arcana, naturalmente. Migliaia di anni di conoscenza degli Alti Nobili donarono al nostro popolo nascente le risorse per prosperare in questa nuova terra.\n\nVi sono le Magicole del fuoco e degli altri elementi; fondamenta naturali del mondo stesso.\n\nPossediamo una curiosa collezione di conoscenze sacre sulla Magicola della Luce. I Gran Sacerdoti di Lunargenta hanno contribuito notevolmente al suo sapere.\n\nInoltre, dato che lo chiedono sempre tutti, ci sono le Magicole proibite...\n\nDel Vuoto. Della vilmagia. Della necromanzia... anche se suppongo che alcune restrizioni si siano... allentate.\n\n<Veldharin si abbandona a uno sguardo corrucciato e pensieroso.>', '', 68974),
(317749, 'itIT', 'Ti indirizzerei alla placca presente nell\'Omnium. Riassume piuttosto bene le intenzioni di Dath\'Remar.\n\nIn breve, aveva svariate ragioni, era molto ambizioso e il suo scopo era chiaro come il sole in tutta Cantoeterno.\n\nDath\'Remar vide molto in gioventù e non si tirò indietro dalle forze magiche del nostro mondo.', '', 68974),
(317748, 'itIT', 'Certo che sì, e non solo per l\'Omnium!\n\nCon la caduta della città, persi due fratelli e la mia cara sorella. Erano tutti e tre dei Magistri...\n\nCercai di assistere il giovane principe nel resuscitare... risvegliarsi? Era così... freddo.\n\nMa a prescindere da cosa tentassimo, semplicemente... si rifiutò. Persino con il suo cifrario chiave, non vi fu risposta.\n\nDopo che venne sigillato, cercai di aiutare i Magistri sopravvissuti a ripristinare la Terrazza... ma insistettero perché mi riposassi.\n\nCosì feci, per un buon numero di anni. Alcuni... non così buoni. Ahimè, sono comunque tornato e il giovane Rommath non è nelle condizioni di cercare di fermarmi.\n\nL\'uscita dalla pensione è esattamente ciò che mi serviva dopo tutti questi anni!', '', 68974),
(317746, 'itIT', 'Be\', nell\'incentivare il porre domande, mi riferivo all\'Omnium, non a me. Ma se ti interessa...\n\nIo sono il Custode Veldharin, designato come Custode della Conoscenza dalla Gran Magistra... ehm... com\'è che si chiamava?\n\nLa Gran Magistra Mo... no, non era lei. Uhm... be\', in ogni caso. Diversi Gran Magistri fa. Ormai ho perso il conto.\n\nDopo la Seconda Guerra, fui... incoraggiato a ritirarmi. Pare che Anasterian volesse che mi \"godessi i molti giorni che mi erano rimasti\".\n\nEra il suo modo di dire che ero troppo vecchio per ricoprire il ruolo. Per cui, andai a vivere con mia figlia, Elsharin.\n\nLei divenne Cercatrice di Sapienza e Ambasciatrice dei Magistri presso il Santuario della Magia a Roccavento.', '', 68974),
(317744, 'itIT', 'Ti do il benvenuto al Licaneum!\n\nTi trovi davanti allo sconfinato sapere e dell\'infinito potenziale magico!\n\nNaturalmente, parlo dell\'Omnium dei Solealto.\n\nIo non sono che l\'umile custode, qui presente per rispondere alle domande e guidare tutti i giovani Magistri nel corso di questo magico viaggio accademico.\n\nQualunque domanda tu abbia, ti basterà porla.', '', 68974),
(317738, 'itIT', 'Perché credi che si chiamino Magicole? Perché non Manacole? Be\', aspetta, assomiglia a manopole.\n\nOnnicole, magari? Ehi, e se si dicesse onni... còle?\n\nOh, per Dath\'Remar, che abbia sempre sbagliato la pronuncia?', 'Perché credi che si chiamino Magicole? Perché non Manacole? Be\', aspetta, assomiglia a manopole.\n\nOnnicole, magari? Ehi, e se si dicesse onni... còle?\n\nOh, per Dath\'Remar, che abbia sempre sbagliato la pronuncia?', 68974),
(317730, 'itIT', 'Non vedevo un tale caos magico nella Terrazza sin da... be\'... dalla tua \"operazione\" con il Magistro Umbric.\n\n<Lo spezzamagie ti squadra dall\'alto in basso.>\n\nComportati a modo, stavolta.', 'Non vedevo un tale caos magico nella Terrazza sin da... be\'... dalla tua \"operazione\" con il Magistro Umbric.\n\n<Lo spezzamagie ti squadra dall\'alto in basso.>\n\nComportati a modo, stavolta.', 68974),
(317724, 'itIT', 'Comportati a modo tra queste sale, $c.\n\nAnche se ci troviamo nella Terrazza dei Magistri, le regole sulla magia vengono ancora applicate con grande rigore.', 'Comportati a modo tra queste sale, $c.\n\nAnche se ci troviamo nella Terrazza dei Magistri, le regole sulla magia vengono ancora applicate con grande rigore.', 68974),
(317723, 'itIT', '<Lo spezzamagie stringe gli occhi e ti guarda ghignante.>\n\nNon temere, $n. Non alzerò la lama contro di te.\n\nMi è stato detto che, l\'ultima volta che sei $ugiunto:giunta; qui, avevi l\'autorità del Reggente. Sappi che la mia risposta non implicava questioni personali.\n\nRispetto il giuramento degli spezzamagie e la... sfortunata serie di eventi alla Terrazza doveva rimanere tra le Corti e i Magistri, non tra me e te.\n\nApprezzo, in ogni caso, che tu non mi abbia ucciso.', '', 68974),
(317722, 'itIT', '<Rommath stringe gli occhi per un istante.>\n\nUmbric e i suoi... seguaci dovranno rispettare le regole sull\'Omnium.\n\nNon lascerò che gli orrori del Vuoto mettano in scena uno spettacolo di magia semplicemente perché i Ren\'dorei non sanno seguire le regole.\n\nTuttavia, per quanto comunque nutra ben poca fiducia nella via percorsa da Umbric, potrei essere incline a fidarmi di lui... per ora.\n\nIl controllo del Vuoto che lui e la sua gente ribadiscono di aver padroneggiato potrebbe permettere discussioni più... approfondite riguardo alla Magicola del Vuoto.\n\nIn ogni caso, non lascerò che la magia del Vuoto diventi un nuovo corso di studi dei Magistri di questa Terrazza!', '', 68974),
(317721, 'itIT', 'Solo ai Magistri è concesso di studiare il sapere al suo interno, e persino in tal caso sono presenti restrizioni.\n\nRegole e limitazioni imposte da Dath\'Remar in persona, generazioni fa.\n\nQueste garantivano che, mentre scoprivamo e catalogavamo nuove e pericolose magie, fossimo protetti anche dalla natura imprevedibile di queste forze.\n\nDetto ciò, ci fu un tempo in cui accedere alla Vilmagicola era severamente proibito.\n\nPensa a quanto rapidamente cambiano i tempi...', '', 68974),
(317719, 'itIT', '<Umbric sorride e guarda Rommath.>\n\nPer quanto Rommath... tolleri a malapena la mia ricerca, l\'Omnium è sempre stato ben protetto con regole e misure di sicurezza.\n\nNon è mai stato un compendio aperto di conoscenza della magia, grazie al cielo.\n\nTremo all\'idea di cosa sarebbe riuscito a fare Dar\'khan se gli fosse stato concesso di adoperarlo.\n\nLe regole attuali esistono sin dai tempi di Dath\'Remar.\n\nI suoi primi scontri con il Vuoto oppure la devastazione di cui fu testimone con la vilmagia durante la Guerra degli Antichi sono l\'esatto motivo per cui tali magie furono messe al bando.\n\nDetto ciò, forse ci sarebbe di che discutere.', '', 68974),
(317717, 'itIT', 'Una domanda che noi tutti ci eravamo posti da quando si è quietato.\n\nNessuno sa esattamente cosa sia successo. Sappiamo solo in che stato venne trovato.\n\nNon ero presente durante la caduta della Terrazza... all\'arrivo di Dar\'khan... ma potei osservarne le conseguenze.\n\nMai avevo visto l\'Omnium tanto vuoto... non un bagliore di potere, non una Magicola a vista.\n\nUna cornice spoglia, silente. Fu quantomeno sconcertante.', '', 68974),
(317715, 'itIT', 'Quando lo trovammo, non era che una cornice vuota in mezzo alle macerie. Niente Magicole. Niente bagliore runico.\n\nA parte le scorie lasciate dal massacro di Dar\'khan, sembrava privo di energia.\n\nLe Magicole erano state create come estensioni dell\'Omnium. Non avevamo mai valutato che fossero pezzi che potevano perdersi.\n\nQuando la reliquia si risvegliò e le Magicole riapparvero, notammo che la matrice centrale era rimasta vuota.\n\nEra un\'anomalia che non avevamo mai osservato prima.\n\nQualunque Magicola vi fosse stata presente per ultima era andata semplicemente perduta o distrutta. In questo caso, rubata.', '', 68974),
(317714, 'itIT', 'All\'inizio, sì.\n\nSapevamo che era giunto alla Terrazza per massacrare l\'assemblea. Le prove erano sparse sulle pareti e sull\'Omnium stesso.\n\nQuando però irrompemmo nella sua dimora ed esaminammo i suoi studi, scoprimmo solo della sua ossessione per le magie più oscure.\n\nIn seguito, Umbric fece notare che il movente di Drathir erano il potere e la conoscenza, e che danneggiare l\'Omnium pareva andare contro le sue... ambizioni.', '', 68974),
(317713, 'itIT', 'Io... non so rispondere.\n\nProvammo di tutto per resuscitare l\'Omnium. Nemmeno il cifrario chiave dei Solealto ebbe alcun effetto.\n\nKael\'thas era... in lutto.\n\nLui, come tutti noi, aveva perso tanto in poco tempo.\n\nStava disperatamente cercando delle soluzioni per il nostro dramma. Per il nostro popolo.\n\nIl sapere contenuto nell\'Omnium avrebbe potuto aiutarci... avrebbe persino potuto guidare il Principe.\n\nQuando però rimase silente, ci trovammo in stallo.', '', 68974),
(316792, 'itIT', 'Cifrario Chiave dei Solealto non riconosciuto. Impronta Eco Speculare attivata.', 'Cifrario Chiave dei Solealto non riconosciuto. Impronta Eco Speculare attivata.', 68974),
(315312, 'itIT', 'Questa è la Torre degli Albastella, il luogo dell\'infanzia di Dar\'khan Drathir. Una volta era un posto ameno e tranquillo.\n\nDopo il mio esilio da Lunargenta, ho cercato varie parti delle ricerche di Dar\'khan nel Vuoto, che poi mi hanno condotto fin qui.\n\nA quanto pare, molte delle sue ricerche sono state svolte in segreto. La cima di questa torre è dove ho aperto un portale per Telogrus la prima volta.\n\nNon pensavo ci fossero altri segreti nascosti qui...', '', 68974),
(314998, 'itIT', 'Non abbiamo mai eletto un cercatore che non fosse un Magistro, ma tu sei... una persona particolarmente adatta.\n\nCome cercatore, ti verranno affidate ricerche da Umbric oppure da me.\n\nIn cambio del completamento di questi incarichi, ti doneremo una serie di potenziamenti runici per migliorare le tue capacità.\n\nTroverai queste rune nel tuo Foglio dell\'Omnium. La scelta di cosa potenziare spetta a te, naturalmente.\n\nDomande?', '', 68974),
(314900, 'itIT', '<Rommath fissa l\'Omnium silenzioso.>\n\nCi siamo quasi. Con il cifrario chiave di Belo\'vir nelle nostre mani e dopo che tu e Umbric avete recuperato la Magicola del Vuoto, resta solo una cosa da fare.\n\nOra o mai più, $n. Iniziamo?', '', 68974),
(314899, 'itIT', 'Ho studiato l\'Omnium per anni. Come ogni Magistro prima di me, ho imparato tutto ciò che poteva insegnarmi: rune, magie, incantesimi, tutto.\n\nIl giorno in cui è sprofondato nel silenzio, è stato un giorno oscuro per diversi motivi. Non avrei mai immaginato che avrebbe vibrato di nuova vita, un giorno. Strano come cambino le cose.', '', 68974),
(314791, 'itIT', 'Sembra che Belo\'vir abbia lasciato istruzioni su come accedere alla sua cripta... istruzioni che hanno atteso che le trovassi per molto tempo.\n\nConoscendo il mio predecessore, non c\'è dubbio che siano state progettate per sfruttare la sua maestria con le immagini speculari.\n\nDovremo dividerci questa sfida. Io andrò al mio ufficio di sopra e mi occuperò dei sigilli più complicati.\n\nPuoi aiutare le mie immagini speculari ad aprire gli altri tre nei livelli esterni?', '', 68974),
(314746, 'itIT', 'Non posso fare a meno di chiedermi da quanto tempo Dar\'khan cercasse i segreti proibiti all\'interno della Magicola del Vuoto.\n\nQuando ci unimmo ai Magistri, ci venne spiegato quali scuole di magia, con le relative Magicole, fossero rigorosamente proibite.\n\nDar\'khan aveva già mostrato un\'inclinazione per il Vuoto durante il periodo trascorso a Dalaran, quindi sapevo che ne fosse quantomeno affascinato.\n\nEra forse ciò che desiderava fin dal primo giorno in cui mettemmo piede nel Licaneum?\n\nO fu una decisione avventata dell\'ultimo momento, presa mentre massacrava i suoi confratelli sulla Terrazza?', '', 68974),
(314744, 'itIT', 'C\'è stato un momento in cui credevo di aver scoperto tutti i segreti che Dar\'khan aveva nascosto in questo posto. Gli eventi di oggi si sono rivelati... inaspettati.\n\nSia per precauzione, e sia perché so che Rommath me lo chiederà, mi assicurerò che non sia rimasto nient\'altro nascosto fra le ombre.\n\nMetterò via gli elementi del nostro rituale e ti raggiungerò alla Terrazza dei Magistri dopo che avrai aiutato Rommath a recuperare il cifrario chiave di Belo\'vir.', '', 68974),
(314678, 'itIT', 'I miei sospetti erano fondati... Non lo senti nell\'aria, $n? Quella pulsazione... fredda e distante, come il battito di un cuore.\n\nCredo sia il componente che stiamo cercando, nascosto appena fuori dalla nostra portata.\n\nCon il focus e la magia giusta, il Vuoto può rivelare i segreti nascosti da Dar\'khan.\n\nMentre colleghi le ancore, io concluderò questo incantesimo.\n\nFai attenzione: il Vuoto ci sta già chiamando verso la nostra destinazione.', '', 68974),
(310354, 'itIT', 'Sarà necessario oltrepassare le sue misure di sicurezza. Aspetterò lì.', '', 68974),
(310059, 'itIT', 'Che si trattasse di Arcano, Vile, Luce o... Vuoto, Dath\'remar creò l\'Omnium per preservare le conoscenze al suo interno.', '', 68974),
(317919, 'itIT', 'Immagino lo facciano in molti.\n\nNormalmente, rivolgerei tutte le domande al nostro Custode della Conoscenza appena uscito dal pensionamento, il Custode Veldharin.\n\nMa visto il tuo ruolo nel ripristino dell\'Omnium, soddisferò la tua curiosità.', '', 68974),
(317754, 'itIT', 'Ah, sì. La Vilmagicola. Un nodo proibito di conoscenza, o perlomeno così era.\n\nLa vilmagia fu la prima che Dath\'Remar indicò come catalizzatore per creare l\'Omnium.\n\nNe vide il potenziale... e l\'orrore durante i giorni degli Alti Nobili. Vide le creature dell\'altro mondo che adoperavano la vilmagia.\n\nQuando giunse il momento, vide la verità distruttiva sia della vilmagia che della magia arcana, durante quegli ultimi giorni della Guerra degli Antichi.\n\nNon avrebbe mai più permesso al suo popolo di lasciarsi accecare da una tale forza ignota e distruttiva.\n\nNel tempo, la conoscenza della vilmagia e della Legione Infuocata fu condivisa tra i Magistri e il Concilio di Tirisfal.\n\nTuttavia, fatta eccezione per pochi eletti, lo studio della Vilmagicola fu proibito.\n\nOh, come cambiano i tempi...', '', 68974),
(317573, 'itIT', 'Questo mondo... tutto il suo potenziale... ora è mio.', '', 68974),
(309931, 'itIT', 'Guardaboschi, tempratevi! Mostrate a questi mostri perché siamo stati scelti per proteggere l\'enclave!', 'Guardaboschi, preparatevi! Mostrate a questi mostri perché siamo stati scelti per proteggere l\'enclave!', 68974),
(307084, 'itIT', 'Ah, $n.\n\nÈ bello vedere un viso meno imbronciato a questo tavolo. Mi tollerano nuovamente all\'interno della mia città, ma segnati le mie parole: da un momento all\'altro Rommath potrebbe sperimentare la sua specialità, i Missili Traslati.\n\nVedi, al tempo combinava la Traslazione e i Missili Arcani per dare una lezione a chiunque fosse abbastanza sciocco da sfidarlo a un duello tra maghi.\n\nNon gli piace ammetterlo, ma fui io a insegnargli come intessere uno strato d\'invisibilità nei missili per non vedere da dove arrivavano.\n\nIn ogni caso, Lor\'themar mi ha concesso di trovarmi qui e mi sto godendo tutto il disagio causato dalla mia presenza.', '', 68974),
(306595, 'itIT', 'Dobbiamo... informare Lor\'themar Theron di quanto successo. Tu inizia ad andare.', '', 68974),
(304405, 'itIT', 'In tempi di guerra e conflitto, i Protettori Antichi sono stati una forza inarrestabile sul campo di battaglia.\n\nPurtroppo, però, ci vuole molto impegno per risvegliarli.\n\nTi farò seguire dai Guardialberi da Battaglia dell\'Antico Scorzaverde. Cerca grosse pietre e macigni che l\'Antico può scagliare contro i nostri nemici.\n\nFinché non avrà qualcosa da lanciare, si rifiuterà di svegliarsi.', 'In tempi di guerra e conflitto, i Protettori Antichi sono stati una forza inarrestabile sul campo di battaglia.\n\nPurtroppo, però, ci vuole molto impegno per risvegliarli.\n\nTi farò seguire dai Guardialberi da Battaglia dell\'Antico Scorzaverde. Cerca grosse pietre e macigni che l\'Antico può scagliare contro i nostri nemici.\n\nFinché non avrà qualcosa da lanciare, si rifiuterà di svegliarsi.', 68974),
(303273, 'itIT', '', 'I Protettori Antichi sono particolarmente utili in battaglia come unità d\'assedio per decimare le retrovie dei nemici.\n\nL\'Orda conosce piuttosto bene la loro potenza distruttiva.', 68974),
(300503, 'itIT', '', 'Non dovrebbe essere possibile. L\'ho inviato con la magia a Ulen, il siniscalco incaricato durante la mia assenza. Potrebbe star accadendo qualcosa di strano a Suramar.', 68974),
(292933, 'itIT', 'Be\'... Ci abbiamo lavorato tanto e te lo sei meritato.', '', 68974),
(289958, 'itIT', '', 'Il Patto d\'Argento torna a Lunargenta, un\'ultima volta.', 68974);
