INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(3033, 'itIT', 'Divoratore Torturato', '|cFFFFD200Zona:|r Val e Naigtal|n|cFFFFD200Impresa:|r Scontri eroici|n|cFFFFD200Mercante:|r Kifaan|n|cFFFFD200Costo:|r 15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 'Sia i Domanaar che gli Eterei hanno tentato di imprigionare questo divoratore, ma hanno sempre fallito. Ora, intriso delle energie del Vuoto, questo mangiatore tormentato è pronto a scatenare il caos.', 68974),
(2990, 'itIT', 'Corazza Nulla Fatuoforgiata', '|cFFFFD200Impresa:|r Un viaggio attraverso le stelle|n|cFFFFD200Zona:|r Naigtal|n|cFFFFD200Mercante:|r Kifaan|n|cFFFFD200Costo:|r 15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 'Assemblata dai Forgialuce, distrutta dagli Hal\'hadar e ripristinata da un Tecnomante. In questa Corazza da Guerra rinnovata turbina una matrice di luce, Vuoto e arcano.', 68974),
(2988, 'itIT', 'Scavastelle del Sacerdote del Vuoto', '|cFFFFD200Impresa:|r Un viaggio tra le stelle|n|cFFFFD200Zona:|r Val|n|cFFFFD200Mercante:|r Kifaan|n|cFFFFD200Costo:|r 15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 'Questo capolavoro della tecnologia di trasporto dei Sacerdoti del Vuoto un tempo era un simbolo di status e potere tra i Domanaar di alto rango. Dopo che il suo creatore è misteriosamente scomparso, usarlo durante i raduni sui mondi cardine ha iniziato a essere considerato sconveniente.', 68974),
(2975, 'itIT', 'Razzo d\'Artificio X-TREMO degli Acqualorda', '|cFFFFD200Emporio|r', 'Gli ingegneri di Cavafonda erano così presi dalla possibilità di creare un razzo più veloce che non si sono fermati a chiedersi se fosse il caso di farlo.', 68974);
